using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Looks up a configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var defaults = new Dictionary<string, string>
        {
            ["app:name"] = "HttpMcpServer",
            ["app:version"] = "1.0.0",
            ["app:environment"] = "Production",
            ["feature:darkMode"] = "true",
        };

        return defaults.TryGetValue(key, out var value)
            ? value
            : $"Unknown key: {key}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Name = "HttpMcpServer",
            Version = "1.0.0",
            Environment = "Production",
            Features = new { DarkMode = true, Analytics = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

