using ModelContextProtocol.AspNetCore;
using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithPromptsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();

app.MapMcp();
app.MapGet("/health", () => "ok");

// List all endpoints on startup
app.Lifetime.ApplicationStarted.Register(() =>
{
    var endpointSources = app.Services.GetService<IEnumerable<Microsoft.AspNetCore.Routing.EndpointDataSource>>();
    if (endpointSources != null)
    {
        foreach (var source in endpointSources)
        {
            foreach (var endpoint in source.Endpoints)
            {
                var routeEndpoint = endpoint as Microsoft.AspNetCore.Routing.RouteEndpoint;
                Console.Error.WriteLine($"Endpoint: {routeEndpoint?.RoutePattern?.RawText ?? endpoint.DisplayName}");
            }
        }
    }
});

app.Run();
